import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.DUZGA-Gz.js";const m=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"reference/troubleshooting.md","filePath":"reference/troubleshooting.md","lastUpdated":1791296613000}'),o={name:"reference/troubleshooting.md"};function s(r,e,d,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="an-attachment-does-not-fit" tabindex="-1">An attachment does not fit <a class="header-anchor" href="#an-attachment-does-not-fit" aria-label="Permalink to &quot;An attachment does not fit&quot;">​</a></h2><p>Print one cell and one attachment base using the same material and profile. Check for elephant&#39;s foot, warping, or excess material before modifying the CAD. If sanding is required, apply it consistently and record it.</p><h2 id="a-threaded-component-binds" tabindex="-1">A threaded component binds <a class="header-anchor" href="#a-threaded-component-binds" aria-label="Permalink to &quot;A threaded component binds&quot;">​</a></h2><p>Remove stringing and debris, then test the matching calibration piece. Keep the part aligned with the thread axis and do not force initial engagement. Record sanding or lubrication because either can change task resistance.</p><h2 id="a-module-moves-during-a-trial" tabindex="-1">An attachment moves during a trial <a class="header-anchor" href="#a-module-moves-during-a-trial" aria-label="Permalink to &quot;An attachment moves during a trial {#a-module-moves-during-a-trial}&quot;">​</a></h2><p>Stop if continuation is unsafe. Preserve the trial result, describe the displacement in <code>notes</code>, and reseat the attachment before continuing. For repeated release, verify cell tolerances and mounting orientation.</p><h2 id="a-printed-part-breaks" tabindex="-1">A printed part breaks <a class="header-anchor" href="#a-printed-part-breaks" aria-label="Permalink to &quot;A printed part breaks&quot;">​</a></h2><p>Record the trial as it occurred. Photograph the damage when useful, replace the component with the same print profile, and note the replacement. Do not substitute an unreported rerun.</p><h2 id="completion-time-appears-as-a-date" tabindex="-1">Completion time appears as a date <a class="header-anchor" href="#completion-time-appears-as-a-date" aria-label="Permalink to &quot;Completion time appears as a date&quot;">​</a></h2><p>Format the spreadsheet column as a plain number and enter decimal seconds without units. Use <code>12.9</code>, not <code>12.9 s</code> or a clock value.</p><h2 id="failed-trials-have-no-time" tabindex="-1">Failed trials have no time <a class="header-anchor" href="#failed-trials-have-no-time" aria-label="Permalink to &quot;Failed trials have no time&quot;">​</a></h2><p>This is expected. <code>completion_time_s</code> is only populated for successful trials. Use <code>outcome=timeout</code> for a trial that reaches the time limit.</p><h2 id="simulation-geometry-loads-at-the-wrong-scale" tabindex="-1">Simulation geometry loads at the wrong scale <a class="header-anchor" href="#simulation-geometry-loads-at-the-wrong-scale" aria-label="Permalink to &quot;Simulation geometry loads at the wrong scale&quot;">​</a></h2><p>Verify the asset units and the loader&#39;s unit conversion. Check both visual and collision geometry before changing the global scene scale.</p><h2 id="a-simulation-joint-moves-in-the-wrong-direction" tabindex="-1">A simulation joint moves in the wrong direction <a class="header-anchor" href="#a-simulation-joint-moves-in-the-wrong-direction" aria-label="Permalink to &quot;A simulation joint moves in the wrong direction&quot;">​</a></h2><p>Inspect the joint axis, parent-child order, and initial pose. Compare the full motion with the physical mechanism, not only the rendered rest configuration.</p><h2 id="simulation-contact-is-unstable" tabindex="-1">Simulation contact is unstable <a class="header-anchor" href="#simulation-contact-is-unstable" aria-label="Permalink to &quot;Simulation contact is unstable&quot;">​</a></h2><p>Begin with one environment and a conservative timestep. Inspect collision geometry, penetration at reset, solver settings, drive gains, and mass ratios. The supplied physical properties are nominal. Identify them for the printed mechanism when studying sim-to-real correspondence.</p><h2 id="an-isaac-lab-asset-cannot-be-found" tabindex="-1">An Isaac Lab asset cannot be found <a class="header-anchor" href="#an-isaac-lab-asset-cannot-be-found" aria-label="Permalink to &quot;An Isaac Lab asset cannot be found&quot;">​</a></h2><p>The simulation repository uses Git submodules. From the repository root, initialize or update them with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span></span></code></pre></div><p>This initializes the pinned dependencies, including HiveBoard assets, Isaac Lab, cuRobo, and the DynaArm description. Newton USD files also need to be generated locally. Check them with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generate_newton_usd.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verify-only</span></span></code></pre></div><p>Follow the <a href="/hivedocs/simulation/isaac-lab#generate-the-newton-assets">asset-generation instructions</a> to create missing files. ANYmal has an additional robot-assembly generator. The <code>--skip-conversion</code> option cannot replace conversion on a fresh clone.</p><h2 id="an-isaac-lab-task-is-not-registered" tabindex="-1">An Isaac Lab task is not registered <a class="header-anchor" href="#an-isaac-lab-task-is-not-registered" aria-label="Permalink to &quot;An Isaac Lab task is not registered&quot;">​</a></h2><p>List all registered tasks without launching the simulator:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/record_all_envs.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span></code></pre></div><p>Use the exact <code>Isaac-HiveBoard-*</code> identifier printed by the script. Robot tokens are case-sensitive, including <code>Anymal</code>. Light-bulb tasks provide both <code>Lamp-v0</code> and <code>Lamp-Play-v0</code> variants for Spot, Franka, and ANYmal. The current Franka ball-valve task uses <code>Franka-BallValve</code>, replacing the earlier <code>Franka-LeverValve</code> identifier.</p><p>If imports fail after updating the repository, run <code>git submodule update --init --recursive</code> and <code>uv sync --python 3.12</code> from its root. Continue using <code>uv run</code> for subsequent commands.</p><h2 id="the-command-editor-does-not-open-in-the-browser" tabindex="-1">The command editor does not open in the browser <a class="header-anchor" href="#the-command-editor-does-not-open-in-the-browser" aria-label="Permalink to &quot;The command editor does not open in the browser&quot;">​</a></h2><p>Start the editor with an explicit port, for example <code>uv run python scripts/command_edit.py --port 9080</code>, and open <code>http://localhost:9080</code> on the computer running it. Use the address printed by the editor if a different port was selected. See <a href="/hivedocs/simulation/workflows#edit-a-task-s-command-sequence">command editing</a> for the complete workflow.</p><h2 id="a-simulation-recording-is-missing" tabindex="-1">A simulation recording is missing <a class="header-anchor" href="#a-simulation-recording-is-missing" aria-label="Permalink to &quot;A simulation recording is missing&quot;">​</a></h2><p>For batch recording, check <code>summary.json</code> and the per-task logs under <code>videos/environments/&lt;timestamp&gt;/</code>. Confirm that <code>ffmpeg</code> and <code>ffprobe</code> are on <code>PATH</code>. The default batch selection includes only <code>-Play</code> environments, including light bulb. Use <code>--task</code> to select one task explicitly, or <code>--all</code> to include all variants. See <a href="/hivedocs/simulation/workflows#record-several-environments">batch recording</a>.</p>',34)])])}const u=a(o,[["render",s]]);export{m as __pageData,u as default};
